# 1. Identify "arrow": a singleton color object with arms >= 3 (thin angle)
# 2. Find the unique same-shape twin pair (shape occurring exactly twice)
# 3. Recolor the farther twin to arrow color

def get_objects(grid):
    """Extract all objects from the grid"""
    height = len(grid)
    width = len(grid[0])
    seen_colors = {}
    objects = []  # list of (color, cells) where cells are [(r,c), ...]

    visited = set()
    for r in range(height):
        for c in range(width):
            if (r, c) in visited:
                continue
            color = grid[r][c]
            if color == 0:  # background
                continue

            obj_cells = [(r, c)]
            (r0, c0) = (r, c)
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    nr, nc = r0 + dr, c0 + dc
                    if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == color and (nr, nc) != (r0, c0):
                        obj_cells.append((nr, nc))

            for (rr, cc) in obj_cells:
                visited.add((rr, cc))

            if len(obj_cells) > 0:
                objects.append((color, obj_cells))

    return objects

def get_corners(color, obj_cells):
    """Find all corners of an object"""
    corners = set()
    for (r, c) in obj_cells:
        # A corner is a cell that has at least one neighbor
        neighbors = []
        for (nr, nc) in obj_cells:
            if (nr, nc) != (r, c):
                neighbors.append(((nr - r) > 0, (nc - c) > 0))
        if neighbors:
            groups = []
            seen_dirs = set()
            for (below, right) in neighbors:
                if (below, right) not in seen_dirs:
                    groups.append((below, right))
                    seen_dirs.add((below, right))
            if len(groups) >= 2:  # Has at least 2 adjacent neighbors
                corners.add((r, c))
    return corners

def get_length_of_side(obj_cells):
    """Get the length of connected segments from object cells"""
    # Returns max horizontal or vertical run from any cell in object
    max_horz = 0
    max_vert = 0
    for (r, c) in obj_cells:
        # Count horizontal neighbors
        horz = 0
